CREATE OR REPLACE FUNCTION public.fn_validar_asignacion_empresa()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare 
  v_emp_cuba bigint; 
  v_emp_disp bigint;
begin
  select b.empresa_id into v_emp_cuba
  from public."CUBA" c 
  join public."BODEGA" b on b.id = c.bodega_id
  where c.id = new.cuba_id;

  select d.empresa_id into v_emp_disp 
  from public."DISPOSITIVO" d 
  where d.id = new.dispositivo_id;

  if v_emp_cuba is distinct from v_emp_disp then
    raise exception 'El dispositivo % (empresa %) no puede asignarse a la cuba % (empresa %)',
      new.dispositivo_id, v_emp_disp, new.cuba_id, v_emp_cuba;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.fn_validar_proceso()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare 
  v_bod_cuba bigint; 
  v_cap numeric; 
  v_bod_perfil bigint;
begin
  select bodega_id, cap_litros into v_bod_cuba, v_cap
  from public."CUBA" 
  where id = new.cuba_id;

  select bodega_id into v_bod_perfil
  from public."PERFIL_FERMENTACION" 
  where id = new.perfil_id;

  if v_bod_cuba is distinct from v_bod_perfil then
    raise exception 'El perfil % pertenece a otra bodega que la cuba %', new.perfil_id, new.cuba_id;
  end if;

  if new.volumen_litros > v_cap then
    raise exception 'El volumen (%) supera la capacidad de la cuba % (%)',
      new.volumen_litros, new.cuba_id, v_cap;
  end if;
  return new;
end $function$
